use clap::Parser;
use serde_json::Value;
use std::fs;
use std::io::{self, Read};

#[derive(Parser, Debug)]
pub struct Args {
    /// Input file (optional). If not provided, reads from stdin (pipe)
    #[arg(short, long)]
    input: Option<String>,

    /// Struct name (default: "AutoGenerated")
    #[arg(short, long, default_value = "AutoGenerated")]
    name: String,

    /// Use json tags
    #[arg(short, long)]
    json: bool,
}

pub fn run(args: &Args) {
    let json_str = read_input(&args.input);

    if json_str.trim().is_empty() {
        panic!("Error: Empty input provided. Pipe JSON or use --input file.json");
    }

    match serde_json::from_str::<Value>(&json_str) {
        Ok(value) => {
            let go_code = format!(
                "type {} {}",
                args.name,
                json_value_to_go_type(&value, args.json, 0)
            );
            println!("{}", go_code);
        }
        Err(e) => {
            panic!("Failed to parse JSON: {}", e);
        }
    }
}

fn read_input(input_file: &Option<String>) -> String {
    if let Some(file) = input_file {
        fs::read_to_string(file).expect("Failed to read from file")
    } else {
        let mut buffer = String::new();
        io::stdin()
            .read_to_string(&mut buffer)
            .expect("Failed to read from stdin");
        buffer
    }
}

fn json_value_to_go_type(value: &Value, with_json_tags: bool, indent: u64) -> String {
    render_type(&infer_type(value), with_json_tags, indent)
}

#[derive(Debug, Clone, PartialEq)]
enum GoType {
    Null,
    Any,
    Bool,
    Int,
    Float,
    /// Numbers mixed with numeric strings ("321", "3.0", ...)
    Number,
    /// A string that parses as a JSON number; renders as string but
    /// merges with numbers into json.Number
    NumericString,
    Str,
    Ptr(Box<GoType>),
    Slice(Box<GoType>),
    Map(Box<GoType>),
    Struct(Vec<(String, GoType)>),
}

fn infer_type(value: &Value) -> GoType {
    match value {
        Value::Null => GoType::Null,
        Value::Bool(_) => GoType::Bool,
        Value::Number(n) => {
            if n.is_f64() {
                GoType::Float
            } else {
                GoType::Int
            }
        }
        Value::String(s) => {
            if serde_json::from_str::<serde_json::Number>(s).is_ok() {
                GoType::NumericString
            } else {
                GoType::Str
            }
        }
        Value::Array(items) => {
            let elem = items
                .iter()
                .map(infer_type)
                .reduce(merge_types)
                .unwrap_or(GoType::Any);
            GoType::Slice(Box::new(elem))
        }
        Value::Object(map) => {
            if map.is_empty() {
                return GoType::Map(Box::new(GoType::Any));
            }
            let fields: Vec<(String, GoType)> = map
                .iter()
                .map(|(k, v)| (k.clone(), infer_type(v)))
                .collect();
            // A keyed collection ({"data": {...}, "data2": {...}}) rather
            // than a record: every value is itself an object
            if map.len() >= 2 && map.values().all(|v| v.is_object()) {
                let value_type = fields
                    .into_iter()
                    .map(|(_, t)| t)
                    .reduce(merge_types)
                    .unwrap();
                GoType::Map(Box::new(value_type))
            } else {
                GoType::Struct(fields)
            }
        }
    }
}

fn merge_types(a: GoType, b: GoType) -> GoType {
    use GoType::*;
    if a == b {
        return a;
    }
    match (a, b) {
        (Null, t) | (t, Null) => match t {
            Any => Any,
            Ptr(inner) => Ptr(inner),
            other => Ptr(Box::new(other)),
        },
        (Any, _) | (_, Any) => Any,
        (Ptr(x), Ptr(y)) => wrap_ptr(merge_types(*x, *y)),
        (Ptr(x), y) | (y, Ptr(x)) => wrap_ptr(merge_types(*x, y)),
        (Int, Float) | (Float, Int) => Float,
        (Int, Number) | (Number, Int) | (Float, Number) | (Number, Float) => Number,
        (Int, NumericString)
        | (NumericString, Int)
        | (Float, NumericString)
        | (NumericString, Float)
        | (Number, NumericString)
        | (NumericString, Number) => Number,
        (Str, NumericString) | (NumericString, Str) => Str,
        (Slice(x), Slice(y)) => Slice(Box::new(merge_types(*x, *y))),
        (Map(x), Map(y)) => Map(Box::new(merge_types(*x, *y))),
        (Struct(f1), Struct(f2)) => merge_structs(f1, f2),
        (Map(m), Struct(f)) | (Struct(f), Map(m)) => {
            let merged = f.into_iter().map(|(_, t)| t).fold(*m, merge_types);
            Map(Box::new(merged))
        }
        _ => Any,
    }
}

fn wrap_ptr(t: GoType) -> GoType {
    match t {
        // any already covers nil
        GoType::Null | GoType::Any => GoType::Any,
        GoType::Ptr(inner) => GoType::Ptr(inner),
        other => GoType::Ptr(Box::new(other)),
    }
}

fn merge_structs(f1: Vec<(String, GoType)>, f2: Vec<(String, GoType)>) -> GoType {
    let mut k1: Vec<&str> = f1.iter().map(|(k, _)| k.as_str()).collect();
    let mut k2: Vec<&str> = f2.iter().map(|(k, _)| k.as_str()).collect();
    k1.sort_unstable();
    k2.sort_unstable();
    if k1 == k2 {
        let mut by_key: std::collections::HashMap<String, GoType> = f2.into_iter().collect();
        GoType::Struct(
            f1.into_iter()
                .map(|(k, t)| {
                    let t2 = by_key.remove(&k).unwrap();
                    let merged = merge_types(t, t2);
                    (k, merged)
                })
                .collect(),
        )
    } else {
        // Same shape but different keys: it is a map, merge all values
        let value_type = f1
            .into_iter()
            .chain(f2)
            .map(|(_, t)| t)
            .reduce(merge_types)
            .unwrap_or(GoType::Any);
        GoType::Map(Box::new(value_type))
    }
}

fn render_type(t: &GoType, with_json_tags: bool, indent: u64) -> String {
    match t {
        GoType::Null | GoType::Any => "any".to_string(),
        GoType::Bool => "bool".to_string(),
        GoType::Int => "int".to_string(),
        GoType::Float => "float64".to_string(),
        GoType::Number => "json.Number".to_string(),
        GoType::Str | GoType::NumericString => "string".to_string(),
        GoType::Ptr(inner) => format!("*{}", render_type(inner, with_json_tags, indent)),
        GoType::Slice(inner) => format!("[]{}", render_type(inner, with_json_tags, indent)),
        GoType::Map(inner) => format!("map[string]{}", render_type(inner, with_json_tags, indent)),
        GoType::Struct(fields) => render_struct(fields, with_json_tags, indent),
    }
}

fn render_struct(fields: &[(String, GoType)], with_json_tags: bool, indent: u64) -> String {
    let field_pad = "    ".repeat(indent as usize + 1);
    let close_pad = "    ".repeat(indent as usize);
    let mut lines = vec!["struct {".to_string()];
    // Consecutive single-line fields are aligned together; a nested
    // struct breaks the alignment block (gofmt behavior)
    let mut block: Vec<(String, String, &str)> = Vec::new();

    for (key, t) in fields {
        let name = make_field_name(key);
        let type_str = render_type(t, with_json_tags, indent + 1);
        if type_str.contains('\n') {
            flush_block(&mut lines, &mut block, &field_pad, with_json_tags);
            let mut line = format!("{}{} {}", field_pad, name, type_str);
            if with_json_tags {
                check_tag(key);
                line.push_str(&format!(" `json:\"{}\"`", key));
            }
            lines.push(line);
        } else {
            block.push((name, type_str, key));
        }
    }
    flush_block(&mut lines, &mut block, &field_pad, with_json_tags);
    lines.push(format!("{}}}", close_pad));
    lines.join("\n")
}

fn flush_block(
    lines: &mut Vec<String>,
    block: &mut Vec<(String, String, &str)>,
    pad: &str,
    with_json_tags: bool,
) {
    if block.is_empty() {
        return;
    }
    let name_w = block
        .iter()
        .map(|(n, _, _)| n.chars().count())
        .max()
        .unwrap();
    let type_w = block
        .iter()
        .map(|(_, t, _)| t.chars().count())
        .max()
        .unwrap();
    for (name, type_str, key) in block.drain(..) {
        if with_json_tags {
            check_tag(key);
            lines.push(format!(
                "{}{:<name_w$} {:<type_w$} `json:\"{}\"`",
                pad, name, type_str, key
            ));
        } else {
            lines.push(format!("{}{:<name_w$} {}", pad, name, type_str));
        }
    }
}

fn check_tag(s: &str) {
    if s.chars()
        .any(|c| c == ',' || c == '\\' || c == '"' || c == '\'')
    {
        panic!(
            "Tag can not contain \",\" or \"\\\" or \"\"\" or \"\'\", you have to implement custom unmarshaler for this field."
        );
    }
}

fn make_field_name(s: &str) -> String {
    let result: String = s
        .trim()
        .split(|c: char| c.is_ascii_punctuation() || c.is_whitespace())
        .filter(|w| !w.is_empty())
        .map(|word| {
            let lowered = word.to_lowercase();
            let mut chars = lowered.chars();
            match chars.next() {
                None => String::new(),
                Some(first) => first.to_uppercase().chain(chars).collect(),
            }
        })
        .collect();

    if result.is_empty() {
        panic!("Cannot make field name for key: \"{}\"", s);
    }

    match result.chars().next() {
        None => panic!("Cannot make field name for key: \"{}\"", s),
        Some(c) => {
            if !c.is_alphabetic() {
                panic!(
                    "Cannot make field name for key (first char is not alphabetic): \"{}\"",
                    s
                )
            }
        }
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    fn generate(json: &str, with_json_tags: bool) -> String {
        let value: Value = serde_json::from_str(json).unwrap();
        json_value_to_go_type(&value, with_json_tags, 0)
    }

    #[test]
    fn test_scalars() {
        assert_eq!(generate("null", true), "any");
        assert_eq!(generate("true", true), "bool");
        assert_eq!(generate("123", true), "int");
        assert_eq!(generate("3.0", true), "float64");
        assert_eq!(generate("\"hello\"", true), "string");
        assert_eq!(generate("\"321\"", true), "string");
    }

    #[test]
    fn test_arrays_number_patterns() {
        assert_eq!(generate("[1, 2, 3]", true), "[]int");
        assert_eq!(generate("[1, 2.0]", true), "[]float64");
        assert_eq!(generate("[1, 2, \"321\"]", true), "[]json.Number");
        assert_eq!(generate("[1.0, 2.0, \"321.0\"]", true), "[]json.Number");
        assert_eq!(generate("[1.1, 2.0, \"3210\"]", true), "[]json.Number");
        assert_eq!(generate("[\"321\", \"322\"]", true), "[]string");
        assert_eq!(generate("[\"321\", \"abc\"]", true), "[]string");
        assert_eq!(generate("[1, \"abc\"]", true), "[]any");
        assert_eq!(generate("[]", true), "[]any");
    }

    #[test]
    fn test_arrays_null_makes_pointer() {
        assert_eq!(generate("[1, 2, null]", true), "[]*int");
        assert_eq!(generate("[1, 2, \"3210\", null]", true), "[]*json.Number");
        assert_eq!(generate("[null, null]", true), "[]any");
        assert_eq!(generate("[1, \"abc\", null]", true), "[]any");
    }

    #[test]
    fn test_object_with_differing_keys_is_map() {
        assert_eq!(
            generate(r#"[{"a": "x"}, {"b": "y", "c": "z"}]"#, true),
            "[]map[string]string"
        );
        assert_eq!(
            generate(r#"[{"a": "x"}, {"b": 1}]"#, true),
            "[]map[string]any"
        );
        assert_eq!(
            generate(r#"[{"a": "x"}, {"b": null}, null]"#, true),
            "[]*map[string]*string"
        );
    }

    #[test]
    fn test_object_of_objects_is_map() {
        assert_eq!(
            generate(r#"{"data": {"a": 1}, "data2": {"a": 2}}"#, true),
            "map[string]struct {\n    A int `json:\"a\"`\n}"
        );
        // a single wrapped object stays a struct
        assert_eq!(
            generate(r#"{"data": {"a": 1}}"#, true),
            "struct {\n    Data struct {\n        A int `json:\"a\"`\n    } `json:\"data\"`\n}"
        );
    }

    #[test]
    fn test_struct_alignment_blocks() {
        let out = generate(
            r#"{"a": "x", "bb": 1, "c": {"dd": "y", "e": null}, "ff": [1, 2.0]}"#,
            true,
        );
        let expected = "\
struct {
    A  string `json:\"a\"`
    Bb int    `json:\"bb\"`
    C struct {
        Dd string `json:\"dd\"`
        E  any    `json:\"e\"`
    } `json:\"c\"`
    Ff []float64 `json:\"ff\"`
}";
        assert_eq!(out, expected);
    }

    #[test]
    fn test_no_tags() {
        let out = generate(r#"{"a": "x", "bb": 1, "c": {"d": null}}"#, false);
        let expected = "\
struct {
    A  string
    Bb int
    C struct {
        D any
    }
}";
        assert_eq!(out, expected);
    }

    #[test]
    fn test_merge_nullability() {
        let out = generate(
            r#"[
                {"a": "x", "b": null, "c": [1,2], "d": {"e": "v"}, "f": 1},
                {"a": null, "b": true, "c": null, "d": null, "f": 2.0}
            ]"#,
            true,
        );
        let expected = "\
[]struct {
    A *string `json:\"a\"`
    B *bool   `json:\"b\"`
    C *[]int  `json:\"c\"`
    D *struct {
        E string `json:\"e\"`
    } `json:\"d\"`
    F float64 `json:\"f\"`
}";
        assert_eq!(out, expected);
    }

    #[test]
    fn test_incompatible_types_become_any() {
        let out = generate(r#"[{"a": 3}, {"a": "value"}]"#, true);
        assert_eq!(out, "[]struct {\n    A any `json:\"a\"`\n}");
    }

    #[test]
    #[should_panic]
    fn test_check_tag_panic() {
        check_tag("hello,world");
        check_tag("hello\\world");
        check_tag("hello\"world");
        check_tag("hello'world");
    }

    #[test]
    fn test_check_tag_ok() {
        check_tag("hello world");
        check_tag("hello...world");
        check_tag("hello/world");
    }

    #[test]
    fn test_make_field_name() {
        assert_eq!(make_field_name("heLLo_world"), "HelloWorld");
        assert_eq!(make_field_name("hello__world"), "HelloWorld");
        assert_eq!(make_field_name("XML_HTTP_*()REQUEST"), "XmlHttpRequest");
        assert_eq!(make_field_name("iPhone"), "Iphone");
        assert_eq!(make_field_name("API_V2_RESPONSE"), "ApiV2Response");
        assert_eq!(make_field_name("user_id"), "UserId");
        assert_eq!(make_field_name("max-100-items"), "Max100Items");
        assert_eq!(make_field_name("_hello.world_"), "HelloWorld");
        assert_eq!(make_field_name("__hEllo.world_"), "HelloWorld");
        assert_eq!(make_field_name("hello"), "Hello");
        assert_eq!(make_field_name("a"), "A");
        assert_eq!(make_field_name("as用a.sjlk"), "As用aSjlk");
    }

    #[test]
    #[should_panic]
    fn test_empty_input() {
        make_field_name("");
    }

    #[test]
    #[should_panic]
    fn test_non_alph_on_first_char() {
        make_field_name("0asjlk");
        make_field_name("用asjlk");
    }

    #[test]
    #[should_panic]
    fn test_only_separators() {
        make_field_name("{");
        make_field_name(",{ \x09");
        make_field_name("_");
        make_field_name(".");
        make_field_name(" ");
        make_field_name("-");
        make_field_name("___ - .");
    }
}
